#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# One-time setup for automated releases of @oakgreencc/agit (docs/releasing.md).
# Run from a checkout of the PR branch:
#
#   gh pr checkout agent/release-workflow && ./scripts/release-setup.sh
#
# Nothing here stores a secret: npm publishes over OIDC trusted publishing, and
# GitHub calls go through your own `gh` login. Every stage checks first and is
# safe to re-run.

TOTAL_STAGES=8

REPO=oakgreencc/agit
PKG=@oakgreencc/agit
BRANCH=agent/release-workflow
SEED_TAG=v0.1.0
SEED_SHA=8b15171be0cf89db4e1b65e19f7eb306cedf29d4 # main when 0.1.0 was cut
ENV_NAME=npm

die() { printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET"; exit 1; }
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

cd "$(git rev-parse --show-toplevel)"

# Preflight: the tools the stages call, before anything is touched.
command -v gh >/dev/null || die "gh is not installed (brew install gh)"
gh auth status >/dev/null 2>&1 || die "gh is not logged in: run  gh auth login"
command -v npm >/dev/null || die "npm is not on PATH"
npm_ok=$(node -e 'const [a,b]=process.argv[1].split(".").map(Number);console.log(a>11||(a===11&&b>=15)?1:0)' "$(npm --version)")
[[ "$npm_ok" == 1 ]] || die "npm $(npm --version) is too old for 'npm trust' (needs >= 11.15): nvm use 24"
[[ "$(git branch --show-current)" == "$BRANCH" ]] || die "check out the PR branch first: gh pr checkout $BRANCH"

banner "agit · automated releases to npm and GitHub"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Seed the $SEED_TAG tag"
say "semantic-release counts from the last tag. $SEED_TAG marks what 0.1.0 is,"
say "so the first automated release is 0.2.0 rather than 1.0.0."
if gh api "repos/$REPO/git/ref/tags/$SEED_TAG" >/dev/null 2>&1; then
  ok "$SEED_TAG already exists"
elif confirm "Create tag $SEED_TAG at ${SEED_SHA:0:7} on $REPO?"; then
  gh api "repos/$REPO/git/refs" -f ref="refs/tags/$SEED_TAG" -f sha="$SEED_SHA" >/dev/null
  ok "created $SEED_TAG"
else
  SKIPPED+=("tag $SEED_TAG at $SEED_SHA")
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sign in to npm"
say "The first publish and the trust setup run as you, with 2FA."
if NPM_USER=$(npm whoami 2>/dev/null); then
  ok "signed in as $NPM_USER"
else
  step "npm login opens the browser; sign in with the account in the oakgreencc org."
  npm login --auth-type=web
  NPM_USER=$(npm whoami)
  ok "signed in as $NPM_USER"
fi
open_url "https://www.npmjs.com/settings/oakgreencc/members"
step "Check that $NPM_USER can publish in the org (owner or admin, or a team with write access)."
step "Check two-factor authentication is on (npm trust refuses otherwise):"
note "  https://www.npmjs.com/settings/$NPM_USER/tfa"
pause "Both true? Press Enter"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "First publish: $PKG@0.1.0"
say "npm trusted publishing can only be set up for a package that exists, so"
say "0.1.0 is published once by hand, from the $SEED_TAG tag in a clean clone."
if npm view "$PKG@0.1.0" version >/dev/null 2>&1; then
  ok "$PKG@0.1.0 is already on npm"
elif confirm "Publish $PKG@0.1.0 publicly now? (cannot be unpublished after 72h)"; then
  tmp=$(mktemp -d)
  git clone --quiet --depth 1 --branch "$SEED_TAG" "https://github.com/$REPO.git" "$tmp/agit"
  note "running the tests (prepublishOnly), then publishing; npm will ask for your 2FA code"
  (cd "$tmp/agit" && npm publish --access public)
  rm -rf "$tmp"
  ok "published $PKG@0.1.0"
  open_url "https://www.npmjs.com/package/$PKG"
else
  SKIPPED+=("first publish of $PKG@0.1.0 (then re-run this wizard)")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Trust GitHub Actions to publish"
say "Binds publishing to $REPO, .github/workflows/release.yml, environment '$ENV_NAME'."
say "After this, no npm token exists anywhere: CI proves who it is with OIDC."
if npm view "$PKG" version >/dev/null 2>&1; then
  if confirm "Add the trusted publisher now?"; then
    npm trust github "$PKG" --repo "$REPO" --file release.yml --env "$ENV_NAME" --allow-publish
    ok "trusted publisher added"
  else
    SKIPPED+=("npm trust github $PKG --repo $REPO --file release.yml --env $ENV_NAME --allow-publish")
  fi
  open_url "https://www.npmjs.com/package/$PKG/access"
  step "Under Trusted publishing, check: GitHub Actions · $REPO · release.yml · $ENV_NAME."
  step "Recommended: Publishing access → 'Require two-factor authentication and disallow tokens' → Update."
  note "Trusted publishing keeps working with tokens disallowed; a leaked token then can't publish."
else
  warn "$PKG is not on npm yet: finish stage 3 first, then re-run."
  SKIPPED+=("npm trusted publisher (needs stage 3)")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub: Actions and the '$ENV_NAME' environment"
enabled=$(gh api "repos/$REPO/actions/permissions" --jq .enabled 2>/dev/null || echo unknown)
allowed=$(gh api "repos/$REPO/actions/permissions" --jq .allowed_actions 2>/dev/null || echo unknown)
if [[ "$enabled" == true ]]; then ok "Actions enabled (allowed: $allowed)"; else warn "Actions enabled: $enabled"; fi
[[ "$allowed" == selected ]] && warn "only selected actions may run: allow actions/checkout and actions/setup-node"
if [[ "$enabled" != true || "$allowed" == selected ]]; then
  open_url "https://github.com/$REPO/settings/actions"
  step "Allow Actions for this repository, including actions created by GitHub."
  pause
fi
say "The release job runs in environment '$ENV_NAME', limited to the main branch,"
say "so only a release from main can ask npm for a publish token."
if confirm "Create or update environment '$ENV_NAME' (deployments from main only)?"; then
  printf '%s' '{"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}' |
    gh api -X PUT "repos/$REPO/environments/$ENV_NAME" --input - >/dev/null
  if ! gh api "repos/$REPO/environments/$ENV_NAME/deployment-branch-policies" --jq '.branch_policies[].name' | grep -qx main; then
    gh api "repos/$REPO/environments/$ENV_NAME/deployment-branch-policies" -f name=main -f type=branch >/dev/null
  fi
  ok "environment '$ENV_NAME': deployments from main only"
else
  SKIPPED+=("environment $ENV_NAME (GitHub creates it unprotected on the first run otherwise)")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Put the workflows in place"
say "agit's App holds no 'workflows' permission (by design), so it staged them"
say "in .github/workflows-staged/. This commit, signed by you, moves them into"
say ".github/workflows/ and deletes the staging folder and this wizard."
if [[ -d .github/workflows-staged ]]; then
  if confirm "Commit and push to $BRANCH?"; then
    mkdir -p .github/workflows
    git mv .github/workflows-staged/release.yml .github/workflows/release.yml
    git mv .github/workflows-staged/ci.yml .github/workflows/ci.yml
    git rm --quiet scripts/release-setup.sh
    git commit --quiet -m "ci: move the release and ci workflows into .github/workflows"
    git push --quiet origin "HEAD:$BRANCH"
    ok "pushed; CI now runs on the PR"
  else
    SKIPPED+=("move .github/workflows-staged/*.yml into .github/workflows/ on $BRANCH")
  fi
else
  ok "already moved"
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Merge the PR"
PR_URL=$(gh pr view "$BRANCH" --repo "$REPO" --json url --jq .url)
say "Merging to main triggers the first automated release."
note "Use a merge commit, not squash: semantic-release reads the branch's"
note "conventional commits, and a squash leaves only the PR title."
open_url "$PR_URL"
step "Wait for the 'ci' checks to go green on the PR."
if [[ "$(gh pr view "$BRANCH" --repo "$REPO" --json state --jq .state)" == MERGED ]]; then
  ok "already merged"
elif confirm "Checks green: merge $PR_URL with a merge commit?"; then
  gh pr merge "$BRANCH" --repo "$REPO" --merge
  ok "merged"
else
  SKIPPED+=("merge $PR_URL (merge commit)")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Watch the first release"
say "Waiting for the release run on main…"
sleep 10
run_id=$(gh run list --repo "$REPO" --workflow release.yml --branch main --limit 1 --json databaseId --jq '.[0].databaseId' 2>/dev/null || true)
if [[ -n "$run_id" ]]; then
  if gh run watch "$run_id" --repo "$REPO" --exit-status; then
    ok "release run succeeded"
  else
    warn "release run failed: gh run view $run_id --repo $REPO --log-failed"
    SKIPPED+=("a green release run (see docs/releasing.md, 'When a release fails')")
  fi
else
  warn "no release run found yet: https://github.com/$REPO/actions/workflows/release.yml"
fi
ok "npm latest: $PKG@$(npm view "$PKG" version 2>/dev/null || echo none)"
gh release view --repo "$REPO" --json tagName,url --jq '"GitHub release: \(.tagName) \(.url)"' 2>/dev/null || true
note "Update the CLI on this node with: npm install -g $PKG"
pause "Press Enter for the summary"

finish
